CREATE TABLE tenant_permission_grants (id varchar(64) PRIMARY KEY,tenant_id varchar(64) NOT NULL,permission_id varchar(64) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY tenant_permission_grants_unique(tenant_id,permission_id),KEY tenant_permission_grants_tenant_idx(tenant_id));
CREATE TABLE tenant_administrators (id varchar(64) PRIMARY KEY,tenant_id varchar(64) NOT NULL,membership_id varchar(64) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY tenant_administrators_unique(tenant_id,membership_id));
CREATE TABLE tenant_roles (id varchar(64) PRIMARY KEY,tenant_id varchar(64) NOT NULL,code varchar(128) NOT NULL,name text NOT NULL,description text NOT NULL,status varchar(32) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY tenant_roles_code_unique(tenant_id,code));
CREATE TABLE tenant_role_permissions (id varchar(64) PRIMARY KEY,tenant_id varchar(64) NOT NULL,role_id varchar(64) NOT NULL,permission_id varchar(64) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY tenant_role_permissions_unique(tenant_id,role_id,permission_id));
CREATE TABLE tenant_member_roles (id varchar(64) PRIMARY KEY,tenant_id varchar(64) NOT NULL,membership_id varchar(64) NOT NULL,role_id varchar(64) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY tenant_member_roles_unique(tenant_id,membership_id,role_id));
